class Solution {
public:
    long long minimumDifference(vector<int>& nums) {
        int n = nums.size() / 3;
        int m = nums.size();
        vector<long long> left(m, 0);
        priority_queue<int> maxH;
        long long curSum = 0;
        for (int i = 0; i < m; i++) {
            maxH.push(nums[i]);
            curSum += nums[i];
            if ((int)maxH.size() > n) {
                curSum -= maxH.top();
                maxH.pop();
            }
            if ((int)maxH.size() == n) left[i] = curSum;
        }
        vector<long long> right(m, 0);
        priority_queue<int, vector<int>, greater<int>> minH;
        curSum = 0;
        for (int i = m - 1; i >= 0; i--) {
            minH.push(nums[i]);
            curSum += nums[i];
            if ((int)minH.size() > n) {
                curSum -= minH.top();
                minH.pop();
            }
            if ((int)minH.size() == n) right[i] = curSum;
        }
        long long ans = LLONG_MAX;
        for (int i = n - 1; i < 2 * n; i++) {
            ans = min(ans, left[i] - right[i + 1]);
        }
        return ans;
    }
};

class Solution {
    public long minimumDifference(int[] nums) {
        int n = nums.length / 3;
        int m = nums.length;
        long[] left = new long[m];
        PriorityQueue<Integer> maxH = new PriorityQueue<>(Collections.reverseOrder());
        long curSum = 0;
        for (int i = 0; i < m; i++) {
            maxH.offer(nums[i]);
            curSum += nums[i];
            if (maxH.size() > n) {
                curSum -= maxH.poll();
            }
            if (maxH.size() == n) left[i] = curSum;
        }
        long[] right = new long[m];
        PriorityQueue<Integer> minH = new PriorityQueue<>();
        curSum = 0;
        for (int i = m - 1; i >= 0; i--) {
            minH.offer(nums[i]);
            curSum += nums[i];
            if (minH.size() > n) {
                curSum -= minH.poll();
            }
            if (minH.size() == n) right[i] = curSum;
        }
        long ans = Long.MAX_VALUE;
        for (int i = n - 1; i < 2 * n; i++) {
            ans = Math.min(ans, left[i] - right[i + 1]);
        }
        return ans;
    }
}

var minimumDifference = function(nums) {
    const n = nums.length / 3;
    const m = nums.length;
    // Simple array sorted binary insertion heap for JS
    const left = new Array(m);
    let leftH = [];
    let sum = 0;
    for (let i = 0; i < m; i++) {
        const val = nums[i];
        // binary insert into sorted leftH (ascending)
        let l = 0, r = leftH.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (leftH[mid] < val) l = mid + 1;
            else r = mid;
        }
        leftH.splice(l, 0, val);
        sum += val;
        if (leftH.length > n) {
            sum -= leftH.pop(); // remove largest
        }
        if (leftH.length === n) left[i] = sum;
    }
    const right = new Array(m);
    let rightH = [];
    sum = 0;
    for (let i = m - 1; i >= 0; i--) {
        const val = nums[i];
        let l = 0, r = rightH.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (rightH[mid] < val) l = mid + 1;
            else r = mid;
        }
        rightH.splice(l, 0, val);
        sum += val;
        if (rightH.length > n) {
            sum -= rightH.shift(); // remove smallest
        }
        if (rightH.length === n) right[i] = sum;
    }
    let ans = Infinity;
    for (let i = n - 1; i < 2 * n; i++) {
        ans = Math.min(ans, left[i] - right[i + 1]);
    }
    return ans;
};
